(@qid, 'Les deux sont des synonymes parfaits', 0, 3),
(@qid, 'L''acquis est biologique, l''inné est social', 0, 4);
INSERT INTO questions (matiere_id, type_id, enonce, explication, source, difficulte) VALUES
