INSERT INTO questions (matiere_id, type_id, enonce, explication, source, difficulte) VALUES
(9, 2, 'Le théorème de Bayes donne P(Bᵢ|A) = ?', 'P(Bᵢ|A) = P(A|Bᵢ)P(Bᵢ) / P(A) est le théorème de Bayes.', 'Programme NS4', 3);
