INSERT INTO questions (matiere_id, type_id, enonce, explication, source, difficulte) VALUES
(9, 2, 'La variance V(X) d''une variable aléatoire X est définie par :', 'V(X) = E(X²) − [E(X)]² = E[(X−E(X))²].', 'Programme NS4', 2);
